def estimate(alerts,events,pricing,budget):
    if isinstance(budget,bool) or not isinstance(budget,(int,float)) or budget<0:raise ValueError('invalid budget')
    ids=set();critical=set()
    for a in alerts:
        aid=a.get('id');sev=a.get('severity')
        if not isinstance(aid,str) or not aid or aid in ids or sev not in ('critical','warning','info'):raise ValueError('invalid alert')
        ids.add(aid)
        if sev=='critical':critical.add(aid)
    costs=0.0;attempts=messages=requests=0
    for event in events:
        members=event.get('alert_ids');receivers=event.get('receivers');retries=event.get('retries',{})
        if not isinstance(members,list) or not members or len(set(members))!=len(members) or not set(members)<=ids:raise ValueError('invalid event members')
        if not isinstance(receivers,list) or not receivers or len(set(receivers))!=len(receivers):raise ValueError('invalid receiver fanout')
        for receiver in receivers:
            if receiver not in pricing:raise ValueError('unknown receiver pricing')
            extra=retries.get(receiver,0)
            if isinstance(extra,bool) or not isinstance(extra,int) or not 0<=extra<=10:raise ValueError('invalid retry count')
            tries=1+extra;attempts+=tries;requests+=1;messages+=tries
            basis=pricing[receiver].get('basis');rate=pricing[receiver].get('unit_cost')
            if basis not in ('per_request','per_message') or isinstance(rate,bool) or not isinstance(rate,(int,float)) or rate<0:raise ValueError('invalid price contract')
            costs+=rate*(1 if basis=='per_request' else tries)
    return {'alert_instances':len(ids),'critical_instances':len(critical),'group_changes':len(events),'requests':requests,'send_attempts':attempts,'billable_messages':messages,'estimated_cost':round(costs,6),'over_budget':costs>budget,'critical_path_suppressed':False}
```

